'use strict';
/** 金花 CLUB — dependency-free multiplayer game server, Node.js 20+. */
const http = require('node:http');
const crypto = require('node:crypto');

const PORT = Number(process.env.PORT || 3000);
const MAX_PLAYERS = 6;
const START_CHIPS = 1000;
const ANTE = 10;
const STAKE_START = 10;
const STAKE_MAX = 320;
const ROOM_TTL = 24 * 60 * 60 * 1000;
const rooms = new Map();
const staticFiles = {
  '/': ['index.html', 'text/html; charset=utf-8'],
  '/index.html': ['index.html', 'text/html; charset=utf-8'],
  '/style.css': ['style.css', 'text/css; charset=utf-8'],
  '/app.js': ['app.js', 'text/javascript; charset=utf-8'],
  '/favicon.svg': ['favicon.svg', 'image/svg+xml'],
};

const embeddedAssets = {
  'index.html': '',
  'style.css': '',
  'app.js': '',
  'favicon.svg': '',
};

function code() {
  const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let result;
  do {
    result = Array.from({ length: 6 }, () => alphabet[crypto.randomInt(alphabet.length)]).join('');
  } while (rooms.has(result));
  return result;
}
function error(message, status = 400) { const e = new Error(message); e.status = status; throw e; }
function randomId() { return crypto.randomBytes(12).toString('hex'); }
function randomToken() { return crypto.randomBytes(24).toString('hex'); }
function nameOf(value) {
  const name = String(value ?? '').trim().replace(/\s+/g, ' ');
  if (!name || [...name].length > 12 || /[<>\x00-\x1f]/.test(name)) error('昵称需为 1–12 个字符，不能含特殊控制字符');
  return name;
}
function getRoom(codeValue) {
  const room = rooms.get(String(codeValue || '').trim().toUpperCase());
  if (!room) error('找不到这个房间，请检查房间码', 404);
  room.touched = Date.now();
  return room;
}
function authenticated(params) {
  const room = getRoom(params.code);
  const player = room.players.find(p => p.id === params.playerId && p.token === params.token);
  if (!player) error('玩家身份已失效，请重新进入房间', 401);
  return { room, player };
}
function handName(category) { return ['单张', '对子', '金花', '顺子', '豹子', '顺金'][category]; }
const RANKS = '23456789TJQKA';
const SUITS = ['♠', '♥', '♣', '♦'];
function newDeck() {
  return SUITS.flatMap(suit => Array.from(RANKS, (symbol, index) => ({ suit, symbol, value: index + 2 })));
}
function shuffledDeck() {
  const cards = newDeck();
  for (let i = cards.length - 1; i > 0; i--) {
    const j = crypto.randomInt(i + 1);
    [cards[i], cards[j]] = [cards[j], cards[i]];
  }
  return cards;
}
function evaluate(cards) {
  const vals = cards.map(c => c.value).sort((a, b) => b - a);
  const flush = cards.every(c => c.suit === cards[0].suit);
  const unique = new Set(vals).size === 3;
  let straightHigh = 0;
  if (unique && vals[0] - vals[2] === 2) straightHigh = vals[0];
  if (unique && vals[0] === 14 && vals[1] === 3 && vals[2] === 2) straightHigh = 3; // A23, lowest straight
  if (vals[0] === vals[2]) return [4, vals[0]];
  if (flush && straightHigh) return [5, straightHigh];
  if (straightHigh) return [3, straightHigh];
  if (flush) return [2, ...vals];
  if (vals[0] === vals[1]) return [1, vals[0], vals[2]];
  if (vals[1] === vals[2]) return [1, vals[1], vals[0]];
  return [0, ...vals];
}
function comparison(a, b) {
  const aa = evaluate(a), bb = evaluate(b);
  for (let i = 0; i < Math.max(aa.length, bb.length); i++) {
    const diff = (aa[i] || 0) - (bb[i] || 0);
    if (diff) return Math.sign(diff);
  }
  return 0;
}
function active(room) { return room.players.filter(p => p.inHand && !p.folded); }
function addLog(room, text) { room.logs.unshift(text); room.logs = room.logs.slice(0, 12); room.lastAction = text; }
function broadcast(room) {
  for (const stream of room.streams) {
    try { stream.write('event: refresh\ndata: {}\n\n'); } catch (_) { room.streams.delete(stream); }
  }
}
function liveConnections(p) { return p.streams.size > 0; }
function sanitized(room, self) {
  return {
    code: room.code, phase: room.phase, hostId: room.hostId, selfId: self.id,
    round: room.round, pot: room.pot, stake: room.stake, turnId: room.turnId,
    maxPlayers: MAX_PLAYERS, ante: ANTE, startChips: START_CHIPS,
    lastAction: room.lastAction, logs: room.logs,
    players: room.players.map(p => ({
      id: p.id, name: p.name, chips: p.chips, isHost: p.id === room.hostId,
      inHand: p.inHand, folded: p.folded, seen: p.seen, connected: liveConnections(p),
      cards: p.id === self.id && (p.seen || room.phase === 'result') ? p.cards : null,
      contribution: p.contribution,
    })),
    result: room.result,
    self: {
      id: self.id, name: self.name,
      canStart: room.hostId === self.id && room.phase !== 'playing' && room.players.filter(p => p.chips >= ANTE + STAKE_START).length >= 2,
      canAct: room.phase === 'playing' && room.turnId === self.id && self.inHand && !self.folded,
      canSee: room.phase === 'playing' && self.inHand && !self.folded && !self.seen,
      callCost: room.stake * (self.seen ? 2 : 1),
      raiseCost: room.stake * 2 * (self.seen ? 2 : 1),
      compareCost: room.stake * (self.seen ? 2 : 1) * 2,
      canCompare: room.phase === 'playing' && room.turnId === self.id && room.actionCount >= room.dealtCount && active(room).length > 1,
      cardCount: self.cards.length,
    },
  };
}
function nextSeat(room, afterId) {
  const startIndex = room.players.findIndex(p => p.id === afterId);
  for (let n = 1; n <= room.players.length; n++) {
    const p = room.players[(startIndex + n + room.players.length) % room.players.length];
    if (p.inHand && !p.folded) return p.id;
  }
  return null;
}
function endHand(room, reason) {
  const remaining = active(room);
  if (remaining.length !== 1) return false;
  const winner = remaining[0];
  const amount = room.pot;
  winner.chips += amount;
  room.result = { winnerId: winner.id, winnerName: winner.name, amount, cards: winner.cards,
    handName: handName(evaluate(winner.cards)[0]), reason };
  room.phase = 'result'; room.turnId = null;
  room.pot = 0;
  addLog(room, `🏆 ${winner.name} 赢得 ${amount} 筹码！`);
  return true;
}
function startHand(room) {
  if (room.phase === 'playing') error('本局还未结束');
  const eligible = room.players.filter(p => p.chips >= ANTE + STAKE_START);
  if (eligible.length < 2) error('至少需要 2 位筹码足够的玩家');
  const deck = shuffledDeck();
  room.phase = 'playing'; room.round++; room.pot = 0; room.stake = STAKE_START;
  room.result = null; room.actionCount = 0; room.dealtCount = eligible.length;
  room.dealerIndex = (room.dealerIndex + 1) % room.players.length;
  for (const player of room.players) {
    player.inHand = eligible.includes(player); player.folded = false; player.seen = false;
    player.cards = player.inHand ? deck.splice(0, 3) : [];
    player.contribution = 0;
    if (player.inHand) { player.chips -= ANTE; player.contribution += ANTE; room.pot += ANTE; }
  }
  const dealer = room.players[room.dealerIndex];
  room.turnId = nextSeat(room, dealer.id);
  addLog(room, `第 ${room.round} 局开始！${eligible.length} 位玩家入场，每人底注 ${ANTE}`);
}
function play(room, player, action, targetId) {
  if (room.phase !== 'playing') error('当前不是游戏进行阶段');
  if (!player.inHand || player.folded) error('你不在本局牌局中');
  if (action === 'see') {
    if (player.seen) error('你已经看过牌了');
    player.seen = true;
    addLog(room, `${player.name} 看牌了`);
    return;
  }
  if (room.turnId !== player.id) error('还没轮到你操作');
  const call = room.stake * (player.seen ? 2 : 1);
  if (action === 'fold') {
    player.folded = true; room.actionCount++;
    addLog(room, `${player.name} 弃牌`);
  } else if (action === 'call') {
    if (player.chips < call) error('筹码不足，可以选择弃牌');
    player.chips -= call; player.contribution += call; room.pot += call; room.actionCount++;
    addLog(room, `${player.name} ${player.seen ? '明' : '闷'}跟 ${call}`);
  } else if (action === 'raise') {
    if (room.stake >= STAKE_MAX) error(`每轮最大基础注额为 ${STAKE_MAX}`);
    const newStake = room.stake * 2;
    const cost = newStake * (player.seen ? 2 : 1);
    if (player.chips < cost) error('筹码不足，无法加注');
    room.stake = newStake; player.chips -= cost; player.contribution += cost; room.pot += cost; room.actionCount++;
    addLog(room, `${player.name} 加注到 ${cost}`);
  } else if (action === 'compare') {
    if (room.actionCount < room.dealtCount) error('所有人至少操作过一次之后才能比牌');
    const target = room.players.find(p => p.id === targetId && p.inHand && !p.folded && p.id !== player.id);
    if (!target) error('请选择一位仍在牌局中的对手');
    const cost = call * 2;
    if (player.chips < cost) error('筹码不足，无法比牌');
    player.chips -= cost; player.contribution += cost; room.pot += cost; room.actionCount++;
    const result = comparison(player.cards, target.cards);
    // Ties cost the challenger the duel, by a clear fixed house rule.
    const loser = result > 0 ? target : player;
    loser.folded = true;
    addLog(room, `${player.name} 与 ${target.name} 比牌，${loser.name} 出局`);
  } else { error('无效的操作'); }
  if (!endHand(room, '牌局结束')) room.turnId = nextSeat(room, player.id);
}
function removePlayer(room, player) {
  if (room.phase === 'playing' && player.inHand && !player.folded) {
    player.folded = true;
    if (room.turnId === player.id) room.turnId = nextSeat(room, player.id);
    addLog(room, `${player.name} 离开并弃牌`);
    endHand(room, '其他玩家离开');
  }
  room.players = room.players.filter(p => p.id !== player.id);
  for (const stream of player.streams) { try { stream.end(); } catch (_) {} room.streams.delete(stream); }
  player.streams.clear();
  if (room.players.length === 0) { rooms.delete(room.code); return; }
  if (room.hostId === player.id) room.hostId = room.players[0].id;
  if (room.dealerIndex >= room.players.length) room.dealerIndex = room.players.length - 1;
  addLog(room, `${player.name} 离开房间`);
  broadcast(room);
}
async function bodyJSON(req) {
  let text = '';
  for await (const chunk of req) {
    text += chunk;
    if (text.length > 16384) error('请求内容过大', 413);
  }
  try { return JSON.parse(text || '{}'); } catch { error('请求格式不正确'); }
}
function json(res, status, data) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff' });
  res.end(JSON.stringify(data));
}
function serveStatic(res, pathname) {
  if (!Object.hasOwn(staticFiles, pathname)) { json(res, 404, { error: 'Not found' }); return; }
  const [filename, mime] = staticFiles[pathname];
  const data = Buffer.from(embeddedAssets[filename], 'base64');
  res.writeHead(200, { 'Content-Type': mime, 'Cache-Control': 'no-cache', 'X-Content-Type-Options': 'nosniff' });
  res.end(data);
}
const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://localhost');
    if (req.method === 'GET' && url.pathname === '/api/health') return json(res, 200, { ok: true, rooms: rooms.size });
    if (req.method === 'POST' && url.pathname === '/api/create') {
      if (rooms.size >= 1000) error('房间数量已达上限，请稍后重试', 503);
      const data = await bodyJSON(req);
      const player = { id: randomId(), token: randomToken(), name: nameOf(data.name), chips: START_CHIPS,
        cards: [], seen: false, folded: false, inHand: false, contribution: 0, streams: new Set() };
      const room = { code: code(), players: [player], hostId: player.id, phase: 'lobby', round: 0, pot: 0,
        stake: STAKE_START, actionCount: 0, dealtCount: 0, turnId: null, dealerIndex: -1,
        streams: new Set(), logs: [], lastAction: '', result: null, touched: Date.now() };
      rooms.set(room.code, room); addLog(room, `${player.name} 创建了房间`);
      return json(res, 200, { code: room.code, playerId: player.id, token: player.token });
    }
    if (req.method === 'POST' && url.pathname === '/api/join') {
      const data = await bodyJSON(req);
      const room = getRoom(data.code);
      const existing = room.players.find(p => p.id === data.playerId && p.token === data.token);
      if (existing) return json(res, 200, { code: room.code, playerId: existing.id, token: existing.token });
      if (room.players.length >= MAX_PLAYERS) error('房间已满（最多 6 人）');
      const player = { id: randomId(), token: randomToken(), name: nameOf(data.name), chips: START_CHIPS,
        cards: [], seen: false, folded: false, inHand: false, contribution: 0, streams: new Set() };
      room.players.push(player); addLog(room, `${player.name} 加入房间`); broadcast(room);
      return json(res, 200, { code: room.code, playerId: player.id, token: player.token });
    }
    if (req.method === 'GET' && url.pathname === '/api/state') {
      const { room, player } = authenticated(Object.fromEntries(url.searchParams));
      return json(res, 200, sanitized(room, player));
    }
    if (req.method === 'GET' && url.pathname === '/api/events') {
      const { room, player } = authenticated(Object.fromEntries(url.searchParams));
      res.writeHead(200, {
        'Content-Type': 'text/event-stream; charset=utf-8',
        'Cache-Control': 'no-cache, no-transform', Connection: 'keep-alive',
        'X-Accel-Buffering': 'no', 'X-Content-Type-Options': 'nosniff',
      });
      res.write('retry: 1500\nevent: refresh\ndata: {}\n\n');
      room.streams.add(res); player.streams.add(res); broadcast(room);
      res.on('close', () => { room.streams.delete(res); player.streams.delete(res); broadcast(room); });
      return;
    }
    if (req.method === 'POST' && url.pathname === '/api/action') {
      const data = await bodyJSON(req);
      const { room, player } = authenticated(data);
      const action = String(data.action || '');
      if (action === 'start') {
        if (player.id !== room.hostId) error('只有房主可以开始新一局', 403);
        startHand(room);
      } else if (action === 'leave') {
        removePlayer(room, player);
        return json(res, 200, { ok: true });
      } else {
        play(room, player, action, data.targetId);
      }
      broadcast(room);
      return json(res, 200, { ok: true });
    }
    if (req.method === 'GET') return serveStatic(res, url.pathname);
    return json(res, 404, { error: 'Not found' });
  } catch (e) {
    json(res, e.status || 500, { error: e.status ? e.message : '服务器出现错误，请重试' });
    if (!e.status) console.error(e);
  }
});
server.keepAliveTimeout = 65000;
setInterval(() => {
  const now = Date.now();
  for (const [key, room] of rooms) {
    if (now - room.touched > ROOM_TTL) { for (const stream of room.streams) stream.end(); rooms.delete(key); }
    else for (const stream of room.streams) { try { stream.write(': ping\n\n'); } catch (_) { room.streams.delete(stream); } }
  }
}, 20000).unref();
if (require.main === module) server.listen(PORT, '0.0.0.0', () => console.log(`金花 CLUB is running at http://localhost:${PORT}`));
module.exports = { server, evaluate, comparison, shuffledDeck };
